    const R = big ? 6 : r.int(1, 4), C = big ? 6 : r.int(1, 4);
    const abc = big ? "ab" : r.pick(["ab", "abc"]);
    const board = Array.from({ length: R }, () => r.str(C, abc).split(""));
    const len = big ? 15 : r.int(1, 7);
    if (r.bool()) return [board, r.str(len, abc)];
    // a random walk, which may step back onto a cell: sometimes valid, sometimes the reuse trap
    let i = r.int(0, R - 1), j = r.int(0, C - 1), w = board[i][j];
    while (w.length < len) {
      const d = r.pick([[1, 0], [-1, 0], [0, 1], [0, -1]]);
      const ni = i + d[0], nj = j + d[1];
      if (ni < 0 || nj < 0 || ni >= R || nj >= C) { if (R * C === 1) break; continue; }
      i = ni; j = nj; w += board[i][j];
    }
    return [board, w];
  }

