function wordOnGrid(board: string[][], word: string): boolean {
  const R = board.length, C = board[0].length;
  const have = new Map<string, number>();
  for (const row of board) for (const ch of row) have.set(ch, (have.get(ch) ?? 0) + 1);
  const need = new Map<string, number>();
  for (const ch of word) need.set(ch, (need.get(ch) ?? 0) + 1);
  for (const [ch, n] of need) if ((have.get(ch) ?? 0) < n) return false; // not enough letters at all
  // fewer starting cells means fewer branches at the top of the tree
  const w = (have.get(word[0])! > have.get(word[word.length - 1])!) ? [...word].reverse().join("") : word;
  const dfs = (r: number, c: number, k: number): boolean => {
    if (r < 0 || c < 0 || r >= R || c >= C || board[r][c] !== w[k]) return false;
    if (k === w.length - 1) return true;
    const ch = board[r][c];
    board[r][c] = "#";
    const found = dfs(r + 1, c, k + 1) || dfs(r - 1, c, k + 1) || dfs(r, c + 1, k + 1) || dfs(r, c - 1, k + 1);
    board[r][c] = ch;
    return found;
  };
  for (let r = 0; r < R; r++) for (let c = 0; c < C; c++) if (dfs(r, c, 0)) return true;
  return false;
}

